const minDelay = 60; 
const maxDelay = 90;
const randomDelayMs = Math.floor(Math.random() * (maxDelay - minDelay + 1)) + minDelay;

return {
  json: {
    ...$input.item.json,
    delay_ms: randomDelayMs
  }
};

const apiData = $input.item.json;
const rides = apiData.rides || [];

const routeData = $('Get Unique Routes').item.json;
const subscribers = routeData.subscribers || [];

const notifications = [];

// Проверяем, вернул ли API ошибку или валидный ответ Atlas
const isInvalidResponse = !apiData || apiData.path === '/api/search' || !Array.isArray(rides);

// Если рейсов нет вовсе или API вернул ошибку/пустой путь
if (isInvalidResponse || rides.length === 0) {
  for (const sub of subscribers) {
    notifications.push({
      json: {
        telegram_id: sub.telegram_id,
        status: 'NO_SCHEDULE',
        message: `ℹ️ По маршруту ${routeData.departure_name} ➔ ${routeData.arrival_name} на ${routeData.date} продажа билетов ещё не открыта.`
      }
    });
  }
  return notifications;
}

// Форматирование цены: если > 500, считаем что это в копейках (3500 -> 35), иначе оставляем как есть
function formatPrice(rawPrice) {
  if (!rawPrice) return 'Н/Д';
  const numericPrice = Number(rawPrice);
  if (isNaN(numericPrice)) return 'Н/Д';
  const finalPrice = numericPrice > 500 ? numericPrice / 100 : numericPrice;
  return `${finalPrice} BYN`;
}

for (const sub of subscribers) {
  const matchingRides = [];

  for (const ride of rides) {
    // Вытаскиваем время из поля ISO строки (например "2026-11-12T05:00:00") или готового HH:mm
    let departureTime = ride.departure || ride.time || '';
    if (departureTime.includes('T')) {
      departureTime = departureTime.split('T')[1].substring(0, 5);
    }

    const freeSeats = ride.free_seats ?? ride.freeSeats ?? 0;

    if (
      departureTime >= sub.time_from &&
      departureTime <= sub.time_to &&
      freeSeats > 0
    ) {
      matchingRides.push({
        time: departureTime,
        price: formatPrice(ride.price),
        free_seats: freeSeats
      });
    }
  }

  if (matchingRides.length > 0) {
    notifications.push({
      json: {
        telegram_id: sub.telegram_id,
        status: 'FOUND',
        message: `🎉 Появились билеты!\n\n🚌 ${routeData.departure_name} ➔ ${routeData.arrival_name}\n📅 Дата: ${routeData.date}\n⏰ Твой интервал: ${sub.time_from} – ${sub.time_to}\n\nРейсы:\n` + 
                 matchingRides.map(r => `• ${r.time} — ${r.price} (Мест: ${r.free_seats})`).join('\n')
      }
    });
  } else {
    notifications.push({
      json: {
        telegram_id: sub.telegram_id,
        status: 'NO_MATCHING_TIME',
        message: `⏳ На ${routeData.date} по маршруту ${routeData.departure_name} ➔ ${routeData.arrival_name} есть рейсы, но на твоё время (${sub.time_from} – ${sub.time_to}) свободных мест пока нет.`
      }
    });
  }
}

return notifications;

